const body = $input.first().json.body;
const avaliacaoUrl = body?.avaliacaoUrl || 'https://g.page/r/CfugOJBgujYPEBM/review';
if (!body || body.evento !== 'avaliacao_google' || body.versao !== 1 ||
    !/^avaliacao-google-v1:[^/]+$/.test(body.idempotencyKey || '')) {
  throw new Error('Pedido de avaliacao invalido.');
}
if (typeof body.email !== 'string' || body.email.length > 120 ||
    !/^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]+$/.test(body.email)) {
  throw new Error('Destinatario invalido.');
}
if (typeof avaliacaoUrl !== 'string' || !/^https:\/\/[^\s]+$/.test(avaliacaoUrl)) {
  throw new Error('Link de avaliacao invalido.');
}
const confirmadoEm = Date.parse(body.confirmadoEm);
if (!Number.isFinite(confirmadoEm) || confirmadoEm > Date.now() + 5 * 60 * 1000 ||
    typeof body.dataAtendimento !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(body.dataAtendimento)) {
  throw new Error('Data do atendimento ou da confirmacao invalida.');
}
const nome = typeof body.nome === 'string' ? body.nome.trim().slice(0, 120) : '';
return [{ json: {
  email: body.email,
  idempotencyKey: body.idempotencyKey,
  assunto: 'Como foi seu atendimento na Camara de Itanhandu?',
  mensagem: (nome ? 'Olá, ' + nome + '!' : 'Olá!') +
    '\n\nObrigado por comparecer ao atendimento da Carteira de Identidade Nacional na Câmara Municipal de Itanhandu.' +
    '\n\nComo foi sua experiência? Se desejar, compartilhe sua opinião em uma avaliação no Google:' +
    '\n' + avaliacaoUrl +
    '\n\nSua participação é voluntária e nos ajuda a melhorar o atendimento.' +
    '\n\nCâmara Municipal de Itanhandu'
} }];

const pedido = $('Preparar convite').first().json;
const resultado = $input.first().json;
if (!Array.isArray(resultado.accepted) ||
    !resultado.accepted.some(email => String(email).toLowerCase() === pedido.email.toLowerCase())) {
  throw new Error('O servidor SMTP nao confirmou a aceitacao do destinatario.');
}
return [{ json: { enviado: true, idempotencyKey: pedido.idempotencyKey } }];
